    { key: `${first.key}-different` },
    { type: first.type + 1 },
    { twin: `${first.twin}-different` },
    { x: first.x + 1 },
    { y: first.y + 1 },
    { rotation: first.rotation + 1 },
    { scale: first.scale + 0.1 },
    { radius: first.radius + 1 },
  ];
  for (const change of changes)
    expect(
      tankRosterIdentity({
        ...design,
        parts: [{ ...first, ...change }, ...design.parts.slice(1)],
